from pyspark.sql import functions as F


def with_fact(df, name, value):
    # Adds a column called name holding the same value on every row.
    return df.withColumn(name, F.lit(value))


def solve(orders):
    status_first = orders.filter(F.col("status") == "paid").filter(F.col("channel") == "web").select("order_id", "total")
    channel_first = orders.filter(F.col("channel") == "web").filter(F.col("status") == "paid").select("order_id", "total")
    a = status_first._jdf.queryExecution().executedPlan().toString()
    b = channel_first._jdf.queryExecution().executedPlan().toString()
    return with_fact(status_first, "same_plan", a == b)
